window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1acfe2363effa148"]={"versions": [{"id": "FIG-1acfe2363effa148", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Timing-Diagramm (SWS COM) zur Veranschaulichung des Übertragungsmodus „Direct / N-Times“ (Use Case A2) für I-PDUs ohne TMS-Umschaltung (Transmission Mode Selector). Dargestellt ist der zeitliche Verlauf von Sendeanforderungen (Send Requests via Com_SendSignal / Com_SendSignalGroup) und den resultierenden Sendezeitpunkten an den darunterliegenden PDU-Router.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Zeitachse: Horizontale Achse $t$.\\n- Sendeanforderung: Blitz-Symbol, gekennzeichnet mit Signalwertzuweisung ($v = x$).\\n- Sendezeitpunkte (Transmissions): Vertikale grüne Pfeile nach unten auf der Zeitachse.\\n- Verworfener/verschobener Sendezeitpunkt: Vertikaler gestrichelter blauer Pfeil nach unten.\\n- Mindestabstand / Filterzeit: $t_{\\mathrm{r,min}}$ (Repetition Period / Minimum Delay Time vor erstem Sendeimpuls) in Orange.\\n- Wiederholungsabstand: $t_{\\mathrm{d}}$ (Repetition Period zwischen N-fachen Wiederholungen) mit horizontalen Pfeilen/Intervallen.\\n- Zeitversatz / Restzeit: $\\mathrm{dt}$ (Zeitspanne zwischen Trigger und geplanter Wiederholung) in Orange.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Drei Szenarien des Übertragungsmodus Direct/N-Times mit $n = 3$ Wiederholungen:\\n1. Regulärer Burst: Ein Sendeaufruf ($v = x$) führt nach Ablauf von $t_{\\mathrm{r,min}}$ zur ersten Sendung; es folgen $n-1 = 2$ Wiederholungen jeweils im festen zeitlichen Abstand $t_{\\mathrm{d}}$.\\n2. Erneuter Trigger während laufendem Burst: Nach einer Sendung und abgelaufener Zeit $\\mathrm{dt}$ trifft eine neue Sendeanforderung ($v = x$) ein. Die verbleibende reguläre Wiederholung wird verworfen (gestrichelter blauer Pfeil) und stattdessen startet nach Ablauf von $t_{\\mathrm{r,min}}$ eine neue Sendesequenz mit $n = 3$ Übertragungen im Abstand $t_{\\mathrm{d}}$.\\n3. Doppelter / dicht aufeinanderfolgender Trigger: Zwei Sendeanforderungen treffen kurz nacheinander ein. Nach dem ersten Sendeimpuls und erneuter Mindestverzögerung $t_{\\mathrm{r,min}}$ wird die Sequenz neu aufgesetzt, sodass der ursprüngliche Wiederholungstakt überschrieben und durch eine vollständige $n$-fache Folge im Abstand $t_{\\mathrm{d}}$ fortgeführt wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ relevant für die Implementierung der PDU-Sende-Engine in AUTOSAR COM gemäß Spezifikationsanforderungen zu DIRECT/N-TIMES Übertragungsmodi: Bei erneuten Sendeanforderungen während einer laufenden N-Times-Sequenz wird die laufende Wiederholungsserie abgebrochen bzw. re-triggert (Restart des N-Times-Zählers auf $n$), unter strikter Einhaltung von Mindestwartezeiten ($t_{\\mathrm{r,min}}$) und Wiederholungsintervallen ($t_{\\mathrm{d}}$).</p>"}, {"id": "FIG-9f3ec35d68b0f187", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Timing-Diagramm (SWS COM) zur Veranschaulichung des Übertragungsmodus „Direct / N-Times“ (Use Case A2) für I-PDUs ohne TMS-Umschaltung (Transmission Mode Selector). Dargestellt ist der zeitliche Verlauf von Sendeanforderungen (Send Requests via Com_SendSignal / Com_SendSignalGroup) und den resultierenden Sendezeitpunkten an den darunterliegenden PDU-Router.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Zeitachse: Horizontale Achse $t$.\\n- Sendeanforderung: Blitz-Symbol, gekennzeichnet mit Signalwertzuweisung ($v = x$).\\n- Sendezeitpunkte (Transmissions): Vertikale grüne Pfeile nach unten auf der Zeitachse.\\n- Verworfener/verschobener Sendezeitpunkt: Vertikaler gestrichelter blauer Pfeil nach unten.\\n- Mindestabstand / Filterzeit: $t_{\\mathrm{r,min}}$ (Repetition Period / Minimum Delay Time vor erstem Sendeimpuls) in Orange.\\n- Wiederholungsabstand: $t_{\\mathrm{d}}$ (Repetition Period zwischen N-fachen Wiederholungen) mit horizontalen Pfeilen/Intervallen.\\n- Zeitversatz / Restzeit: $\\mathrm{dt}$ (Zeitspanne zwischen Trigger und geplanter Wiederholung) in Orange.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Drei Szenarien des Übertragungsmodus Direct/N-Times mit $n = 3$ Wiederholungen:\\n1. Regulärer Burst: Ein Sendeaufruf ($v = x$) führt nach Ablauf von $t_{\\mathrm{r,min}}$ zur ersten Sendung; es folgen $n-1 = 2$ Wiederholungen jeweils im festen zeitlichen Abstand $t_{\\mathrm{d}}$.\\n2. Erneuter Trigger während laufendem Burst: Nach einer Sendung und abgelaufener Zeit $\\mathrm{dt}$ trifft eine neue Sendeanforderung ($v = x$) ein. Die verbleibende reguläre Wiederholung wird verworfen (gestrichelter blauer Pfeil) und stattdessen startet nach Ablauf von $t_{\\mathrm{r,min}}$ eine neue Sendesequenz mit $n = 3$ Übertragungen im Abstand $t_{\\mathrm{d}}$.\\n3. Doppelter / dicht aufeinanderfolgender Trigger: Zwei Sendeanforderungen treffen kurz nacheinander ein. Nach dem ersten Sendeimpuls und erneuter Mindestverzögerung $t_{\\mathrm{r,min}}$ wird die Sequenz neu aufgesetzt, sodass der ursprüngliche Wiederholungstakt überschrieben und durch eine vollständige $n$-fache Folge im Abstand $t_{\\mathrm{d}}$ fortgeführt wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ relevant für die Implementierung der PDU-Sende-Engine in AUTOSAR COM gemäß Spezifikationsanforderungen zu DIRECT/N-TIMES Übertragungsmodi: Bei erneuten Sendeanforderungen während einer laufenden N-Times-Sequenz wird die laufende Wiederholungsserie abgebrochen bzw. re-triggert (Restart des N-Times-Zählers auf $n$), unter strikter Einhaltung von Mindestwartezeiten ($t_{\\mathrm{r,min}}$) und Wiederholungsintervallen ($t_{\\mathrm{d}}$).</p>"}, {"id": "FIG-eaa5250eeed0bb8a", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Timing-Diagramm (SWS COM) zur Veranschaulichung des Übertragungsmodus „Direct / N-Times“ (Use Case A2) für I-PDUs ohne TMS-Umschaltung (Transmission Mode Selector). Dargestellt ist der zeitliche Verlauf von Sendeanforderungen (Send Requests via Com_SendSignal / Com_SendSignalGroup) und den resultierenden Sendezeitpunkten an den darunterliegenden PDU-Router.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Zeitachse: Horizontale Achse $t$.\\n- Sendeanforderung: Blitz-Symbol, gekennzeichnet mit Signalwertzuweisung ($v = x$).\\n- Sendezeitpunkte (Transmissions): Vertikale grüne Pfeile nach unten auf der Zeitachse.\\n- Verworfener/verschobener Sendezeitpunkt: Vertikaler gestrichelter blauer Pfeil nach unten.\\n- Mindestabstand / Filterzeit: $t_{\\mathrm{r,min}}$ (Repetition Period / Minimum Delay Time vor erstem Sendeimpuls) in Orange.\\n- Wiederholungsabstand: $t_{\\mathrm{d}}$ (Repetition Period zwischen N-fachen Wiederholungen) mit horizontalen Pfeilen/Intervallen.\\n- Zeitversatz / Restzeit: $\\mathrm{dt}$ (Zeitspanne zwischen Trigger und geplanter Wiederholung) in Orange.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Drei Szenarien des Übertragungsmodus Direct/N-Times mit $n = 3$ Wiederholungen:\\n1. Regulärer Burst: Ein Sendeaufruf ($v = x$) führt nach Ablauf von $t_{\\mathrm{r,min}}$ zur ersten Sendung; es folgen $n-1 = 2$ Wiederholungen jeweils im festen zeitlichen Abstand $t_{\\mathrm{d}}$.\\n2. Erneuter Trigger während laufendem Burst: Nach einer Sendung und abgelaufener Zeit $\\mathrm{dt}$ trifft eine neue Sendeanforderung ($v = x$) ein. Die verbleibende reguläre Wiederholung wird verworfen (gestrichelter blauer Pfeil) und stattdessen startet nach Ablauf von $t_{\\mathrm{r,min}}$ eine neue Sendesequenz mit $n = 3$ Übertragungen im Abstand $t_{\\mathrm{d}}$.\\n3. Doppelter / dicht aufeinanderfolgender Trigger: Zwei Sendeanforderungen treffen kurz nacheinander ein. Nach dem ersten Sendeimpuls und erneuter Mindestverzögerung $t_{\\mathrm{r,min}}$ wird die Sequenz neu aufgesetzt, sodass der ursprüngliche Wiederholungstakt überschrieben und durch eine vollständige $n$-fache Folge im Abstand $t_{\\mathrm{d}}$ fortgeführt wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ relevant für die Implementierung der PDU-Sende-Engine in AUTOSAR COM gemäß Spezifikationsanforderungen zu DIRECT/N-TIMES Übertragungsmodi: Bei erneuten Sendeanforderungen während einer laufenden N-Times-Sequenz wird die laufende Wiederholungsserie abgebrochen bzw. re-triggert (Restart des N-Times-Zählers auf $n$), unter strikter Einhaltung von Mindestwartezeiten ($t_{\\mathrm{r,min}}$) und Wiederholungsintervallen ($t_{\\mathrm{d}}$).</p>"}], "trans": [{"from": "FIG-1acfe2363effa148", "to": "FIG-9f3ec35d68b0f187", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-9f3ec35d68b0f187", "to": "FIG-eaa5250eeed0bb8a", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Gesamte linke und mittlere Diagrammhälfte (Zeitachse, Sendeimpulse, Blitz-Symbole, Beschriftungen): Kontrast bzw. Helligkeit verändert (blassere Darstellung / reduzierter Kontrast).</li>\n</ul>"}]};
